// Mirror the fixed command sequences in cfs_scenario_runner.py. The catalog
// supplies ordinary command steps; phase parameters below are generated by the
// packaged runner and may depend on telemetry from earlier steps.
const tcRequestId = '전송 시 생성 (16-bit REQUEST_ID)'
const pspRequestId = '전송 시 생성 (32-bit REQUEST_ID)'
const targetLogIndex = 'LAST_CLOSED_INDEX (seal-target 단계 결과)'
const pointerSlot = 'POINTER_SLOT (map 단계 결과)'
const bufferAddress = 'BUFFER_ADDRESS (baseline 단계 PAYLOAD_DATA_STATE)'
const guardAddress = 'GUARD_ADDRESS (baseline 단계 PAYLOAD_DATA_STATE)'

const tc = (packet, parameters = {}) => ({ packet, parameters })
const tcRequest = (packet, parameters) => tc(packet, { ...parameters, REQUEST_ID: tcRequestId })
const pspDebug = (packet, parameters = {}) => tc(packet, { ...parameters, REQUEST_ID: pspRequestId })

const tcLogPlan = {
  'seal-baseline': [tcRequest('CI_LOG_SEAL_CMD', { RESERVED: 0 })],
  'record-normal': [
    tc('CFE_ES_SEND_HK_CMD'),
    tcRequest('TC_CAMERA_CAPTURE_CMD', { FILENAME: 'orbit.png' }),
  ],
  'seal-target': [tcRequest('CI_LOG_SEAL_CMD', { RESERVED: 0 })],
  'read-before': [tcRequest('CI_LOG_READ_CMD', { FILE_INDEX: targetLogIndex, OFFSET: 0 })],
  'overwrite-log': [tcRequest('TC_CAMERA_CAPTURE_CMD', { FILENAME: '../log/tc<LAST_CLOSED_INDEX:04d>.log' })],
  'read-after': [tcRequest('CI_LOG_READ_CMD', { FILE_INDEX: targetLogIndex, OFFSET: 0 })],
  'confirm-continuity': [tcRequest('CI_LOG_STATUS_CMD', { RESERVED: 0 })],
}

const pspPlan = {
  baseline: [tc('PAYLOAD_DATA_STATUS_CMD')],
  map: [pspDebug('MM_CMD_DEBUG_MAP')],
  'deny-direct-write': [pspDebug('MM_CMD_DEBUG_WRITE', {
    WIDTH_BYTES: 1, ADDRESS: bufferAddress, VALUE: 0, RESERVED: 0,
  })],
  pause: [tc('PAYLOAD_DATA_PAUSE_CMD')],
  'read-pointer': [pspDebug('MM_CMD_DEBUG_READ', { WIDTH_BYTES: 4, ADDRESS: pointerSlot })],
  'write-pointer': [pspDebug('MM_CMD_DEBUG_WRITE', {
    WIDTH_BYTES: 4, ADDRESS: pointerSlot, VALUE: guardAddress, RESERVED: 0,
  })],
  'verify-pointer': [pspDebug('MM_CMD_DEBUG_READ', { WIDTH_BYTES: 4, ADDRESS: pointerSlot })],
  resume: [tc('PAYLOAD_DATA_RESUME_CMD')],
  'confirm-sigsegv': [],
}

/** A null result means an unrecognised step, not a verified read-only step. */
export function stepCommandPlan(step) {
  if (step.type === 'command') return [tc(step.packet, step.parameters || {})]
  if (step.type === 'tcLogPhase') return tcLogPlan[step.phase] || null
  if (step.type === 'pspPhase') return pspPlan[step.phase] || null
  if (step.type === 'crcByte') return [tc('CS_CMD_ONE_SHOT', {
    ADDRESS: `XKEY_HK.KEY_ADDRESS (locate-key 단계 결과) + ${step.offset}`,
    SIZE: 1, MAX_BYTES_PER_CYCLE: 1,
  })]
  if (['delay', 'waitTelemetry', 'resolveAddress', 'verifyXbandFrame'].includes(step.type)) return []
  return null
}

export function formatPlannedParameters(parameters) {
  return JSON.stringify(parameters, null, 2)
}
